    public string? Appointment { get; set; }

    /// <summary>On or after this day or time. A day alone means 00:00 UTC.</summary>
    [JsonPropertyName("from")]
    public string? From { get; set; }

    /// <summary>On or before this day or time. A day alone means 23:59:59 UTC.</summary>
    [JsonPropertyName("to")]
    public string? To { get; set; }

    /// <summary>Between 1 and 100. Default 20.</summary>
    [JsonPropertyName("limit")]
    public long? Limit { get; set; }

    /// <summary>Cursor: the id of the last item of the previous page.</summary>
    [JsonPropertyName("starting_after")]
    public string? StartingAfter { get; set; }
}

/// <summary>Parameters of `GET /analytics/summary`.</summary>
public sealed class AnalyticsRetrieveSummaryOptions
{
    /// <summary>The use case whose figures you want. Each use case has its own; today only `appointments`.</summary>
    [JsonPropertyName("use_case")]
    public string? UseCase { get; set; }

    /// <summary>Days covered, ending today.</summary>
    [JsonPropertyName("range")]
    public string? Range { get; set; }

    /// <summary>Only this appointment type.</summary>
    [JsonPropertyName("type")]
    public string? Type { get; set; }

    /// <summary>Only this location.</summary>
    [JsonPropertyName("location")]
    public string? Location { get; set; }
}
